import operator
import re
import sys

_DIV_ERR = "#DIV/0!"
_CYCLE_ERR = "#CYCLE!"

_TOKEN = re.compile(r"\s*(?:(\d+)|([A-Z]+\d*)|(<>|<=|>=|[-+*/(),:=<>]))")
_ARITH = {"+": operator.add, "-": operator.sub, "*": operator.mul}
_COMPARE = {
    "=": operator.eq,
    "<>": operator.ne,
    "<": operator.lt,
    "<=": operator.le,
    ">": operator.gt,
    ">=": operator.ge,
}


def _tokenize(text):
    tokens = []
    text = text.rstrip()
    pos = 0
    while pos < len(text):
        m = _TOKEN.match(text, pos)
        if m is None:
            raise ValueError(f"bad formula: {text!r}")
        if m.group(1) is not None:
            tokens.append(("num", int(m.group(1))))
        elif m.group(2) is not None:
            word = m.group(2)
            tokens.append(("ref" if word[-1].isdigit() else "name", word))
        else:
            tokens.append(("op", m.group(3)))
        pos = m.end()
    return tokens


def _parse(tokens):
    pos = 0

    def peek(offset=0):
        j = pos + offset
        return tokens[j] if j < len(tokens) else ("end", None)

    def advance():
        nonlocal pos
        tok = peek()
        pos += 1
        return tok

    def expect(op):
        if advance() != ("op", op):
            raise ValueError(f"expected {op!r}")

    def formula():
        node = term()
        while peek() in (("op", "+"), ("op", "-")):
            op = advance()[1]
            node = ("bin", op, node, term())
        return node

    def term():
        node = factor()
        while peek() in (("op", "*"), ("op", "/")):
            op = advance()[1]
            node = ("bin", op, node, factor())
        return node

    def factor():
        if peek() == ("op", "-"):
            advance()
            return ("neg", factor())
        return atom()

    def atom():
        kind, text = advance()
        if kind in ("num", "ref"):
            return (kind, text)
        if (kind, text) == ("op", "("):
            node = formula()
            expect(")")
            return node
        if kind == "name":
            return call(text)
        raise ValueError("unexpected token")

    def argument():
        if peek()[0] == "ref" and peek(1) == ("op", ":"):
            first = advance()[1]
            advance()
            return ("range", first, advance()[1])
        return formula()

    def call(name):
        expect("(")
        if name == "IF":
            left = formula()
            op = advance()
            if op[0] != "op" or op[1] not in _COMPARE:
                raise ValueError("expected comparison operator")
            right = formula()
            expect(",")
            then = formula()
            expect(",")
            other = formula()
            expect(")")
            return ("if", left, op[1], right, then, other)
        args = [argument()]
        while peek() == ("op", ","):
            advance()
            args.append(argument())
        expect(")")
        return ("func", name, args)

    return formula()


def _range_names(first, second):
    col_a, row_a = first[0], int(first[1:])
    col_b, row_b = second[0], int(second[1:])
    lo_col, hi_col = sorted((ord(col_a), ord(col_b)))
    lo_row, hi_row = sorted((row_a, row_b))
    for row in range(lo_row, hi_row + 1):
        for col in range(lo_col, hi_col + 1):
            yield f"{chr(col)}{row}"


def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    trees = {}
    for name, content in cells.items():
        text = content.strip()
        if text.startswith("="):
            trees[name] = _parse(_tokenize(text[1:]))
        else:
            trees[name] = ("num", int(text))

    values = {}
    active = set()

    def cell_value(name):
        if name not in cells:
            return 0
        if name in values:
            return values[name]
        if name in active:
            return _CYCLE_ERR
        active.add(name)
        value = evaluate(trees[name])
        active.discard(name)
        values[name] = value
        return value

    def evaluate(node):
        kind = node[0]
        if kind == "num":
            return node[1]
        if kind == "ref":
            return cell_value(node[1])
        if kind == "neg":
            value = evaluate(node[1])
            return value if isinstance(value, str) else -value
        if kind == "bin":
            left = evaluate(node[2])
            if isinstance(left, str):
                return left
            right = evaluate(node[3])
            if isinstance(right, str):
                return right
            op = node[1]
            if op == "/":
                if right == 0:
                    return _DIV_ERR
                quotient = abs(left) // abs(right)
                return quotient if (left < 0) == (right < 0) else -quotient
            return _ARITH[op](left, right)
        if kind == "if":
            left = evaluate(node[1])
            if isinstance(left, str):
                return left
            right = evaluate(node[3])
            if isinstance(right, str):
                return right
            branch = node[4] if _COMPARE[node[2]](left, right) else node[5]
            return evaluate(branch)
        return aggregate(node)

    def aggregate(node):
        _, name, args = node
        collected = []
        for arg in args:
            if arg[0] == "range":
                for cell_name in _range_names(arg[1], arg[2]):
                    if cell_name in cells:
                        value = cell_value(cell_name)
                        if isinstance(value, str):
                            return value
                        collected.append(value)
            else:
                value = evaluate(arg)
                if isinstance(value, str):
                    return value
                collected.append(value)
        if name == "SUM":
            return sum(collected)
        if not collected:
            return 0
        return min(collected) if name == "MIN" else max(collected)

    limit = sys.getrecursionlimit()
    sys.setrecursionlimit(max(limit, 100000))
    try:
        return {name: cell_value(name) for name in cells}
    finally:
        sys.setrecursionlimit(limit)
